fn putDouble(outp:[*]u8,off:usize,x:f64)void{const bits=@as(u64,@bitCast(x));for(0..8)|k|{outp[off+k]=@truncate(bits>>(8*k));}}
export fn n_body_simulation(v:[*]const i64,n:usize,outp:[*]u8,cap:usize)i64{if(n<6)return -1;const nb=v[0];const steps=v[1];const dtm=v[2];const gm=v[3];const tf=v[4];const sm=v[5];if(nb<2 or nb>4 or steps<0 or steps>4 or dtm<1 or dtm>1000 or gm<0 or gm>1000 or tf<1 or tf>10 or sm<1 or sm>3000 or n!=6+5*@as(usize,@intCast(nb)))return -1;const count:usize=@intCast(nb);var x=[_]f64{0}**4;var y=[_]f64{0}**4;var vx=[_]f64{0}**4;var vy=[_]f64{0}**4;var mass=[_]f64{0}**4;for(0..count)|i|{const a=v[6+5*i];const b=v[7+5*i];const c=v[8+5*i];const d=v[9+5*i];const m=v[10+5*i];if(a < -1000 or a>1000 or b < -1000 or b>1000 or c < -100 or c>100 or d < -100 or d>100 or m<1 or m>1000)return -1;x[i]=@floatFromInt(a);y[i]=@floatFromInt(b);vx[i]=@floatFromInt(c);vy[i]=@floatFromInt(d);mass[i]=@floatFromInt(m);}const dt=(@as(f64,@floatFromInt(dtm))/1000.0)*@as(f64,@floatFromInt(tf));const g=@as(f64,@floatFromInt(gm))/1000.0;const soft=@as(f64,@floatFromInt(sm))/1000.0;for(0..@intCast(steps))|_|{for(0..count)|i|{var fx:f64=0;var fy:f64=0;for(0..count)|j|{if(i!=j){const dx=x[j]-x[i];const dy=y[j]-y[i];const dist=@sqrt(dx*dx+dy*dy+soft);const cube=dist*dist*dist;fx+=g*mass[j]*dx/cube;fy+=g*mass[j]*dy/cube;}}vx[i]+=fx*dt;vy[i]+=fy*dt;}for(0..count)|i|{x[i]+=vx[i]*dt;y[i]+=vy[i]*dt;}}const bytes=count*32;if(cap<bytes)return -2;for(0..count)|i|{putDouble(outp,4*i*8,x[i]);putDouble(outp,(4*i+1)*8,y[i]);putDouble(outp,(4*i+2)*8,vx[i]);putDouble(outp,(4*i+3)*8,vy[i]);}return @intCast(bytes);}
